import { createMiddleware } from "@tanstack/react-start";
import { Effect, Option } from "effect";
import type { ManagedRuntime, Scope } from "effect";
import { HttpServerRequest, HttpServerResponse } from "effect/unstable/http";

import {
  StartMiddlewareNextError,
  StartMiddlewareOptionalResponseError,
} from "./errors.js";

export {
  StartMiddlewareNextError,
  StartMiddlewareOptionalResponseError,
} from "./errors.js";

export interface StartOptionalResponseMiddlewareOptions<R, ER, E> {
  readonly onPassThroughResponse?:
    | ((response: Response) => Response)
    | undefined;
  readonly program: Effect.Effect<
    Option.Option<HttpServerResponse.HttpServerResponse>,
    E,
    HttpServerRequest.HttpServerRequest | Scope.Scope | R
  >;
  readonly runtime: ManagedRuntime.ManagedRuntime<R, ER>;
}

export interface StartOptionalResponseHandlerMiddlewareOptions {
  readonly onPassThroughResponse?:
    | ((response: Response) => Response)
    | undefined;
  readonly optionalResponse: (
    request: Request
  ) => Promise<Option.Option<Response>>;
}

export interface StartOptionalWebResponseProgramOptions<R, E> {
  readonly program: Effect.Effect<
    Option.Option<HttpServerResponse.HttpServerResponse>,
    E,
    HttpServerRequest.HttpServerRequest | Scope.Scope | R
  >;
  readonly request: Request;
}

export interface StartPassThroughProgramOptions<A> {
  readonly next: Effect.Effect<A, StartMiddlewareNextError>;
  readonly onPassThroughResponse?:
    | ((response: Response) => Response)
    | undefined;
}

export const startOptionalWebResponseProgram = <R, E>({
  program,
  request,
}: StartOptionalWebResponseProgramOptions<R, E>) =>
  Effect.gen(function* startOptionalWebResponseProgram() {
    const handled = yield* Effect.scoped(
      program.pipe(
        Effect.provideService(
          HttpServerRequest.HttpServerRequest,
          HttpServerRequest.fromWeb(request)
        )
      )
    );

    return handled.pipe(
      Option.map((response) =>
        HttpServerResponse.toWeb(response, {
          withoutBody: request.method === "HEAD",
        })
      )
    );
  });

export const startPassThroughProgram = <
  A extends { readonly response: Response },
>({
  next,
  onPassThroughResponse,
}: StartPassThroughProgramOptions<A>) =>
  next.pipe(
    Effect.map((result) =>
      Option.fromUndefinedOr(onPassThroughResponse).pipe(
        Option.match({
          onNone: () => result,
          onSome: (mutateResponse) => ({
            ...result,
            response: mutateResponse(result.response),
          }),
        })
      )
    )
  );

export const makeStartOptionalResponseMiddleware = <R, ER, E>({
  onPassThroughResponse,
  program,
  runtime,
}: StartOptionalResponseMiddlewareOptions<R, ER, E>) =>
  createMiddleware().server(({ next, request }) =>
    runtime.runPromise(
      Effect.gen(function* startOptionalResponseMiddleware() {
        const handled = yield* startOptionalWebResponseProgram({
          program,
          request,
        });

        return yield* Option.match(handled, {
          onNone: () =>
            startPassThroughProgram({
              next: Effect.tryPromise({
                catch: (cause) => new StartMiddlewareNextError({ cause }),
                try: () => Promise.resolve(next()),
              }),
              onPassThroughResponse,
            }),
          onSome: (response) => Effect.succeed(response),
        });
      })
    )
  );

export const makeStartOptionalResponseHandlerMiddleware = ({
  onPassThroughResponse,
  optionalResponse,
}: StartOptionalResponseHandlerMiddlewareOptions) =>
  createMiddleware().server(({ next, request }) =>
    Effect.runPromise(
      Effect.gen(function* startOptionalResponseHandlerMiddleware() {
        const handled = yield* Effect.tryPromise({
          catch: (cause) => new StartMiddlewareOptionalResponseError({ cause }),
          try: () => optionalResponse(request),
        });

        return yield* Option.match(handled, {
          onNone: () =>
            startPassThroughProgram({
              next: Effect.tryPromise({
                catch: (cause) => new StartMiddlewareNextError({ cause }),
                try: () => Promise.resolve(next()),
              }),
              onPassThroughResponse,
            }),
          onSome: (response) => Effect.succeed(response),
        });
      })
    )
  );

export type StartOptionalResponseMiddleware = ReturnType<
  typeof makeStartOptionalResponseMiddleware
>;
import { assert, it } from "@effect/vitest";
import { Effect, Option } from "effect";
import { HttpServerRequest, HttpServerResponse } from "effect/unstable/http";
import { describe } from "vitest";

import {
  makeStartOptionalResponseHandlerMiddleware,
  makeStartOptionalResponseMiddleware,
  startOptionalWebResponseProgram,
  startPassThroughProgram,
} from "../src/index.js";
import { testRuntime } from "./runtime.js";

const handledProgram = Effect.gen(function* handledProgram() {
  const request = yield* HttpServerRequest.HttpServerRequest;
  return Option.some(
    HttpServerResponse.text(request.url, {
      headers: {
        "x-effect-start": "handled",
      },
    })
  );
});

const passThroughProgram = Effect.succeed(
  Option.none<HttpServerResponse.HttpServerResponse>()
);

const nextResult = (request: Request, response = new Response("next")) => ({
  pathname: new URL(request.url).pathname,
  request,
  response,
});

describe("@bundjil/effect-start TanStack request middleware adapter", () => {
  it.effect("returns an Effect HTTP response without calling next", () =>
    Effect.gen(function* testHandledResponse() {
      const request = new Request("https://bundjil.local/handled");
      const response = yield* startOptionalWebResponseProgram({
        program: handledProgram,
        request,
      }).pipe(Effect.map(Option.getOrThrow));

      assert.strictEqual(response.status, 200);
      assert.strictEqual(response.headers.get("x-effect-start"), "handled");
      assert.strictEqual(
        yield* Effect.promise(() => response.text()),
        "/handled"
      );
    })
  );

  it.effect(
    "falls through to TanStack next when the program returns none",
    () =>
      Effect.gen(function* testPassThrough() {
        const request = new Request("https://bundjil.local/pass");
        const result = yield* startPassThroughProgram({
          next: Effect.succeed(
            nextResult(
              request,
              new Response("next", {
                headers: {
                  "x-next": "called",
                },
              })
            )
          ),
        });

        assert.strictEqual(result.response.headers.get("x-next"), "called");
        assert.strictEqual(
          yield* Effect.promise(() => result.response.text()),
          "next"
        );
      })
  );

  it.effect("omits handled response bodies for HEAD requests", () =>
    Effect.gen(function* testHeadWithoutBody() {
      const request = new Request("https://bundjil.local/handled", {
        method: "HEAD",
      });
      const response = yield* startOptionalWebResponseProgram({
        program: handledProgram,
        request,
      }).pipe(Effect.map(Option.getOrThrow));

      assert.strictEqual(yield* Effect.promise(() => response.text()), "");
    })
  );

  it.effect("mutates pass-through responses with the configured policy", () =>
    Effect.gen(function* testPassThroughMutation() {
      const request = new Request("https://bundjil.local/pass");
      const result = yield* startPassThroughProgram({
        next: Effect.succeed(
          nextResult(
            request,
            new Response("next", {
              headers: {
                "content-type": "text/html; charset=utf-8",
              },
            })
          )
        ),
        onPassThroughResponse: (response) => {
          const headers = new Headers(response.headers);
          headers.set("vary", "Accept, User-Agent");
          return new Response(response.body, {
            headers,
            status: response.status,
            statusText: response.statusText,
          });
        },
      });

      assert.strictEqual(
        result.response.headers.get("vary"),
        "Accept, User-Agent"
      );
      assert.strictEqual(
        yield* Effect.promise(() => result.response.text()),
        "next"
      );
    })
  );

  it.effect(
    "constructs a TanStack middleware backed by the provided runtime",
    () =>
      Effect.sync(() => {
        const middleware = makeStartOptionalResponseMiddleware({
          program: passThroughProgram,
          runtime: testRuntime,
        });

        assert.isFunction(middleware.options.server);
      })
  );

  it.effect(
    "constructs a TanStack middleware backed by a server-only response handler",
    () =>
      Effect.sync(() => {
        const middleware = makeStartOptionalResponseHandlerMiddleware({
          optionalResponse: () => Promise.resolve(Option.none()),
        });

        assert.isFunction(middleware.options.server);
      })
  );
});


