      get: (logical) => Effect.tryPromise({ try: () => client.get<string>(key(logical)), catch: (cause) => new UpstashPersistenceProviderError({ cause }) }).pipe(Effect.map((value) => value ?? undefined), Effect.mapError(() => nativeError("get"))),
      set: (logical, value) => Effect.tryPromise({ try: () => client.set(key(logical), value), catch: (cause) => new UpstashPersistenceProviderError({ cause }) }).pipe(Effect.asVoid, Effect.mapError(() => nativeError("set"))),
