import { Duration, Effect } from "effect";
import * as TestClock from "effect/testing/TestClock";
import * as KeyValueStore from "effect/unstable/persistence/KeyValueStore";

import { AtomicKeyValueStore } from "../src/index.js";
import type { AtomicKeyValueStoreTransaction } from "../src/index.js";
import { PersistenceMemory } from "../src/memory.layer.js";

const transaction = (conditions: AtomicKeyValueStoreTransaction["conditions"], mutations: AtomicKeyValueStoreTransaction["mutations"]): AtomicKeyValueStoreTransaction => ({ conditions, mutations });

it.effect("shares state between native persistence and atomic transactions", () =>
  Effect.gen(function* sharedMemoryContract() {
    const atomic = yield* AtomicKeyValueStore;
    const native = yield* KeyValueStore.KeyValueStore;
    assert.strictEqual(
      yield* atomic.transact(transaction([{ _tag: "Absent", key: "one" }], [{ _tag: "Set", key: "one", value: "first" }])),
      "applied"
    );
    assert.strictEqual(yield* native.get("one"), "first");
    assert.strictEqual(
      yield* atomic.transact(transaction([{ _tag: "Equals", key: "one", value: "other" }], [{ _tag: "Remove", key: "one" }])),
      "conflict"
    );
    assert.strictEqual(yield* native.get("one"), "first");
  }).pipe(Effect.provide(PersistenceMemory))
);

it.effect("commits every successful mutation and rejects duplicate transaction keys", () =>
  Effect.gen(function* atomicContract() {
    const atomic = yield* AtomicKeyValueStore;
    const native = yield* KeyValueStore.KeyValueStore;
    assert.strictEqual(
      yield* atomic.transact(transaction([{ _tag: "Absent", key: "one" }], [
        { _tag: "Set", key: "one", value: "first" },
        { _tag: "Set", key: "two", value: "second" }
      ])),
      "applied"
    );
    assert.strictEqual(yield* native.size, 2);
    yield* atomic.transact(transaction([{ _tag: "Absent", key: "duplicate" }, { _tag: "Absent", key: "duplicate" }], [{ _tag: "Set", key: "duplicate", value: "value" }])).pipe(
      Effect.flip,
      Effect.tap(() => native.get("duplicate").pipe(Effect.tap((value) => Effect.sync(() => assert.strictEqual(value, undefined)))))
    );
  }).pipe(Effect.provide(PersistenceMemory))
);

it.effect("expires atomic TTL values and persistent sets remove expiry", () =>
  Effect.gen(function* ttlContract() {
    const atomic = yield* AtomicKeyValueStore;
    const native = yield* KeyValueStore.KeyValueStore;
    yield* atomic.transact(transaction([{ _tag: "Absent", key: "ttl" }], [{ _tag: "Set", key: "ttl", value: "temporary", ttl: Duration.millis(1) }]));
    yield* TestClock.adjust(Duration.millis(2));
    assert.strictEqual(yield* native.get("ttl"), undefined);
    yield* atomic.transact(transaction([{ _tag: "Absent", key: "ttl" }], [{ _tag: "Set", key: "ttl", value: "durable" }]));
    yield* TestClock.adjust(Duration.millis(2));
    assert.strictEqual(yield* native.get("ttl"), "durable");
  }).pipe(Effect.provide(PersistenceMemory))
);
