import { Duration, Schema } from "effect";

export const AtomicKeyValueStoreKey = Schema.NonEmptyString;
export type AtomicKeyValueStoreKey = typeof AtomicKeyValueStoreKey.Type;

export const AtomicKeyValueStoreValue = Schema.String;
export type AtomicKeyValueStoreValue = typeof AtomicKeyValueStoreValue.Type;

const PositiveWholeMilliseconds = Schema.Int.pipe(
  Schema.check(Schema.isGreaterThan(0))
);

export const AtomicKeyValueStoreTtl = PositiveWholeMilliseconds.pipe(
  Schema.decodeTo(Schema.DurationFromMillis),
  Schema.check(
    Schema.makeFilter((ttl) => Number.isSafeInteger(Duration.toMillis(ttl)), {
      expected: "a positive finite whole-millisecond Duration",
    })
  )
);
export type AtomicKeyValueStoreTtl = typeof AtomicKeyValueStoreTtl.Type;

export const AtomicKeyValueStoreCondition = Schema.Union([
  Schema.TaggedStruct("Absent", { key: AtomicKeyValueStoreKey }),
  Schema.TaggedStruct("Equals", {
    key: AtomicKeyValueStoreKey,
    value: AtomicKeyValueStoreValue,
  }),
]);
export type AtomicKeyValueStoreCondition =
  typeof AtomicKeyValueStoreCondition.Type;

export const AtomicKeyValueStoreMutation = Schema.Union([
  Schema.TaggedStruct("Set", {
    key: AtomicKeyValueStoreKey,
    value: AtomicKeyValueStoreValue,
    ttl: Schema.optional(AtomicKeyValueStoreTtl),
  }),
  Schema.TaggedStruct("Remove", { key: AtomicKeyValueStoreKey }),
]);
export type AtomicKeyValueStoreMutation =
  typeof AtomicKeyValueStoreMutation.Type;

const BoundedNonEmpty = <S extends Schema.Top>(schema: S) =>
  Schema.NonEmptyArray(schema).pipe(Schema.check(Schema.isMaxLength(32)));

export const AtomicKeyValueStoreTransaction = Schema.Struct({
  conditions: BoundedNonEmpty(AtomicKeyValueStoreCondition),
  mutations: BoundedNonEmpty(AtomicKeyValueStoreMutation),
});
export type AtomicKeyValueStoreTransaction =
  typeof AtomicKeyValueStoreTransaction.Type;

export const AtomicKeyValueStoreOutcome = Schema.Literals([
  "applied",
  "conflict",
]);
export type AtomicKeyValueStoreOutcome = typeof AtomicKeyValueStoreOutcome.Type;

export const AtomicKeyValueStoreOperation = Schema.Literals(["transact"]);
export type AtomicKeyValueStoreOperation =
  typeof AtomicKeyValueStoreOperation.Type;
import { Context, Effect, HashSet, Schema } from "effect";

import {
  AtomicKeyValueStoreOperation,
  AtomicKeyValueStoreTransaction,
} from "./schemas.js";
import type { AtomicKeyValueStoreTransaction as AtomicKeyValueStoreTransactionType ,
  AtomicKeyValueStoreOutcome} from "./schemas.js";

export class AtomicKeyValueStoreError extends Schema.TaggedErrorClass<AtomicKeyValueStoreError>()(
  "AtomicKeyValueStoreError",
  {
    operation: AtomicKeyValueStoreOperation,
    message: Schema.NonEmptyString,
  }
) {}

export interface AtomicKeyValueStoreShape {
  readonly transact: (
    transaction: AtomicKeyValueStoreTransactionType
  ) => Effect.Effect<
    typeof AtomicKeyValueStoreOutcome.Type,
    AtomicKeyValueStoreError
  >;
}

export class AtomicKeyValueStore extends Context.Service<
  AtomicKeyValueStore,
  AtomicKeyValueStoreShape
>()("@bundjil/effect-persistence/AtomicKeyValueStore") {}

/** Internal shared public-boundary validation for both adapters. */
const decodeAtomicKeyValueStoreTransactionEffect = Effect.fn(
  "AtomicKeyValueStore.decodeTransaction"
)(function* (transaction: AtomicKeyValueStoreTransactionType) {
  const encoded = yield* Schema.encodeEffect(AtomicKeyValueStoreTransaction)(
    transaction
  );
  const decoded = yield* Schema.decodeUnknownEffect(
    AtomicKeyValueStoreTransaction
  )(encoded);
  const conditionKeys = HashSet.map(
    HashSet.fromIterable(decoded.conditions),
    (condition) => condition.key
  );
  const mutationKeys = HashSet.map(
    HashSet.fromIterable(decoded.mutations),
    (mutation) => mutation.key
  );
  if (
    HashSet.size(conditionKeys) !== decoded.conditions.length ||
    HashSet.size(mutationKeys) !== decoded.mutations.length
  ) {
    return yield* new AtomicKeyValueStoreError({
      operation: "transact",
      message: "Invalid atomic key-value transaction.",
    });
  }
  return decoded;
});

export const decodeAtomicKeyValueStoreTransaction = (
  transaction: AtomicKeyValueStoreTransactionType
) =>
  decodeAtomicKeyValueStoreTransactionEffect(transaction).pipe(
    Effect.mapError(
      () =>
        new AtomicKeyValueStoreError({
          operation: "transact",
          message: "Invalid atomic key-value transaction.",
        })
    )
  );
import {
  Clock,
  Context,
  Duration,
  Effect,
  Layer,
  SynchronizedRef,
} from "effect";
import * as KeyValueStore from "effect/unstable/persistence/KeyValueStore";

import {
  AtomicKeyValueStore,
  decodeAtomicKeyValueStoreTransaction,
} from "./atomic-key-value-store.service.js";

type MemoryEntry = Readonly<{ value: string; expiresAt: number | undefined }>;
type MemoryState = ReadonlyMap<string, MemoryEntry>;

const liveEntries = (state: MemoryState, now: number): MemoryState => {
  const next = new Map(state);
  for (const [key, entry] of state) {
    if (entry.expiresAt !== undefined && entry.expiresAt <= now)
      {next.delete(key);}
  }
  return next;
};

/** A coherent process-local native and atomic store, intended for deterministic tests. */
export const PersistenceMemory: Layer.Layer<
  KeyValueStore.KeyValueStore | AtomicKeyValueStore
> = Layer.effectContext(
  Effect.gen(function* PersistenceMemoryLayer() {
    const state = yield* SynchronizedRef.make<MemoryState>(new Map());
    const read = (key: string) =>
      Effect.gen(function* readMemoryValue() {
        const now = yield* Clock.currentTimeMillis;
        return yield* SynchronizedRef.modify(state, (current) => {
          const live = liveEntries(current, now);
          return [live.get(key)?.value, live] as const;
        });
      });
    const remove = (key: string) =>
      Effect.sync(() =>
        SynchronizedRef.modify(state, (current) => {
          const next = new Map(current);
          next.delete(key);
          return [undefined, next] as const;
        })
      ).pipe(Effect.flatten);
    const native = KeyValueStore.makeStringOnly({
      get: read,
      set: (key, value) =>
        Effect.sync(() =>
          SynchronizedRef.modify(state, (current) => {
            const next = new Map([
              ...current,
              [key, { value, expiresAt: undefined }]
            ]);
            return [undefined, next] as const;
          })
        ).pipe(Effect.flatten),
      remove,
      clear: SynchronizedRef.set(state, new Map()),
      size: Effect.gen(function* memorySize() {
        const now = yield* Clock.currentTimeMillis;
        return yield* SynchronizedRef.modify(state, (current) => {
          const live = liveEntries(current, now);
          return [live.size, live] as const;
        });
      }),
    });
    const atomic = AtomicKeyValueStore.of({
      transact: (transaction) =>
        Effect.gen(function* transactMemoryAtomicKeyValueStore() {
          const decoded =
            yield* decodeAtomicKeyValueStoreTransaction(transaction);
          const now = yield* Clock.currentTimeMillis;
          return yield* SynchronizedRef.modify(state, (current) => {
            const live = liveEntries(current, now);
            const conflict = decoded.conditions.some((condition) =>
              condition._tag === "Absent"
                ? live.has(condition.key)
                : live.get(condition.key)?.value !== condition.value
            );
            if (conflict) {return ["conflict" as const, live] as const;}
            const next = new Map(live);
            for (const mutation of decoded.mutations) {
              if (mutation._tag === "Remove") {next.delete(mutation.key);}
              else
                {next.set(mutation.key, {
                  value: mutation.value,
                  expiresAt:
                    mutation.ttl === undefined
                      ? undefined
                      : now + Duration.toMillis(mutation.ttl),
                });}
            }
            return ["applied" as const, next] as const;
          });
        }),
    });
    return Context.empty().pipe(
      Context.add(KeyValueStore.KeyValueStore, native),
      Context.add(AtomicKeyValueStore, atomic)
    );
  })
);


