    const conditions = Array.replicate({ _tag: "Absent" as const, key: "same" }, 32);
    const mutations = Array.replicate({ _tag: "Set" as const, key: "same", value: "value" }, 32);
    yield* Schema.decodeUnknownEffect(AtomicKeyValueStoreTransaction)({ conditions, mutations });
    const tooManyConditions = Array.replicate({ _tag: "Absent" as const, key: "same" }, 33);
    yield* Schema.decodeUnknownEffect(AtomicKeyValueStoreTransaction)({
      conditions: tooManyConditions,
      mutations: [{ _tag: "Set", key: "same", value: "value" }],
    }).pipe(Effect.flip);
  })
