    const decoded = yield* Schema.decodeUnknownEffect(Schema.fromJsonString(Schema.toCodecJson(AtomicKeyValueStoreTransaction)))(json);
    assert.strictEqual(decoded.mutations[0]._tag, "Set");
    yield* Effect.all([0, 1.5, Infinity].map((ttl) => Schema.decodeUnknownEffect(AtomicKeyValueStoreTtl)(ttl).pipe(Effect.flip)));
  })
);

