  "allows exactly thirty-two entries and rejects thirty-three at Schema decoding",
  () =>
    Effect.gen(function* boundsContract() {
      const conditions = Array.replicate(
        { _tag: "Absent" as const, key: "same" },
        32
      );
      const mutations = Array.replicate(
        { _tag: "Set" as const, key: "same", value: "value" },
        32
      );
      yield* Schema.decodeUnknownEffect(AtomicKeyValueStoreTransaction)({
        conditions,
        mutations,
      });
      const tooManyConditions = Array.replicate(
        { _tag: "Absent" as const, key: "same" },
        33
      );
      yield* Schema.decodeUnknownEffect(AtomicKeyValueStoreTransaction)({
        conditions: tooManyConditions,
        mutations: [{ _tag: "Set", key: "same", value: "value" }],
      }).pipe(Effect.flip);
    })
);

it.effect(
  "rejects duplicate condition and mutation keys before changing state",
  () =>
    Effect.gen(function* duplicateContract() {
      const atomic = yield* AtomicKeyValueStore;
      const native = yield* KeyValueStore.KeyValueStore;
      yield* atomic
        .transact(
          transaction(
            [
              { _tag: "Absent", key: "condition" },
              { _tag: "Absent", key: "condition" },
            ],
            [{ _tag: "Set", key: "condition", value: "value" }]
          )
        )
        .pipe(Effect.flip);
      yield* atomic
        .transact(
          transaction(
            [{ _tag: "Absent", key: "mutation" }],
            [
              { _tag: "Set", key: "mutation", value: "one" },
              { _tag: "Set", key: "mutation", value: "two" },
            ]
          )
        )
        .pipe(Effect.flip);
      assert.strictEqual(yield* native.size, 0);
    }).pipe(Effect.provide(PersistenceMemory))
);

it.effect(
  "selects one concurrent absent-key winner and fences stale owners",
  () =>
    Effect.gen(function* concurrencyContract() {
      const atomic = yield* AtomicKeyValueStore;
      const native = yield* KeyValueStore.KeyValueStore;
      const outcomes = yield* Effect.all(
        Array.map(["one", "two", "three"], (owner) =>
          atomic.transact(
            transaction(
              [{ _tag: "Absent", key: "claim" }],
              [{ _tag: "Set", key: "claim", value: owner }]
            )
          )
        ),
        { concurrency: "unbounded" }
      );
      assert.strictEqual(
        Array.filter(outcomes, (outcome) => outcome === "applied").length,
        1
      );
