import { Redis } from "@upstash/redis";
import {
  Context,
  Data,
  Duration,
  Effect,
  HashSet,
  Layer,
  Redacted,
  Schema,
} from "effect";
import * as KeyValueStore from "effect/unstable/persistence/KeyValueStore";

import {
  AtomicKeyValueStore,
  decodeAtomicKeyValueStoreTransaction,
} from "./atomic-key-value-store.service.js";
import { AtomicKeyValueStoreError } from "./errors.js";

export const UpstashPersistenceKeyPrefix = Schema.String.pipe(
  Schema.check(Schema.isPattern(/^[^*?[\]]+$/))
);
export type UpstashPersistenceKeyPrefix =
  typeof UpstashPersistenceKeyPrefix.Type;

export const UpstashPersistenceOptions = Schema.Struct({
  restUrl: Schema.Redacted(Schema.NonEmptyString),
  restToken: Schema.Redacted(Schema.NonEmptyString),
  keyPrefix: UpstashPersistenceKeyPrefix,
});
export type UpstashPersistenceOptions = typeof UpstashPersistenceOptions.Type;

class UpstashPersistenceProviderError extends Data.TaggedError(
  "UpstashPersistenceProviderError"
)<{ readonly cause: unknown }> {}

const scanPage = Schema.Tuple([Schema.String, Schema.Array(Schema.String)]);
const atomicTransactionScript =
  "local n=tonumber(ARGV[1]); local i=2; for c=1,n do local t=ARGV[i]; local k=KEYS[tonumber(ARGV[i+1])]; if (t=='a' and redis.call('get',k)~=false) or (t=='e' and redis.call('get',k)~=ARGV[i+2]) then return 0 end; i=i+(t=='a' and 2 or 3) end; local m=tonumber(ARGV[i]); i=i+1; for c=1,m do local t=ARGV[i]; local k=KEYS[tonumber(ARGV[i+1])]; if t=='r' then redis.call('del',k); i=i+2 else local v=ARGV[i+2]; local ttl=ARGV[i+3]; if ttl=='' then redis.call('set',k,v) else redis.call('set',k,v,'PX',ttl) end; i=i+4 end end; return 1";

/** Prefix-scoped maintenance scans are weakly consistent and must not coordinate state. */
export const UpstashPersistenceLive = (
  options: UpstashPersistenceOptions
): Layer.Layer<KeyValueStore.KeyValueStore | AtomicKeyValueStore> =>
  Layer.effectContext(
    Effect.sync(function UpstashPersistenceLayer() {
      const client = new Redis({
        url: Redacted.value(options.restUrl),
        token: Redacted.value(options.restToken),
        enableTelemetry: false,
        automaticDeserialization: false,
      });
      const key = (logical: string) => `${options.keyPrefix}${logical}`;
      const nativeError = (method: string) =>
        new KeyValueStore.KeyValueStoreError({
          method,
          message: "Unable to access the persistence store.",
        });
      const scanKeys = Effect.gen(function* scanUpstashKeys() {
        let cursor = "0";
        let keys = HashSet.empty<string>();
        do {
          const page = yield* Effect.tryPromise({
            try: () =>
              client.scan(cursor, {
                match: `${options.keyPrefix}*`,
                count: 100,
              }),
            catch: (cause) => new UpstashPersistenceProviderError({ cause }),
          });
          const [nextCursor, pageKeys] = yield* Schema.decodeUnknownEffect(
            scanPage
          )(page).pipe(
            Effect.mapError(
              () => new UpstashPersistenceProviderError({ cause: undefined })
            )
          );
          cursor = nextCursor;
          keys = HashSet.union(keys, HashSet.fromIterable(pageKeys));
        } while (cursor !== "0");
        return keys;
      });
      const native = KeyValueStore.makeStringOnly({
        get: (logical) =>
          Effect.tryPromise({
            try: () => client.get<string>(key(logical)),
            catch: (cause) => new UpstashPersistenceProviderError({ cause }),
          }).pipe(
            Effect.map((value) => value ?? undefined),
            Effect.mapError(() => nativeError("get"))
          ),
        set: (logical, value) =>
