import type { AtomicKeyValueStore } from "./atomic-key-value-store.service.js";
import { makeUpstashPersistenceLayer } from "./upstash-layer.internal.js";
export { UpstashPersistenceKeyPrefix, UpstashPersistenceOptions } from "./upstash-options.js";
export type { UpstashPersistenceKeyPrefix, UpstashPersistenceOptions } from "./upstash-options.js";
import type { UpstashPersistenceOptions } from "./upstash-options.js";

export const UpstashPersistenceLive = (
  options: UpstashPersistenceOptions
): Layer.Layer<KeyValueStore.KeyValueStore | AtomicKeyValueStore> =>
  makeUpstashPersistenceLayer(options, () =>
    new Redis({
        url: Redacted.value(options.restUrl),
        token: Redacted.value(options.restToken),
        enableTelemetry: false,
        automaticDeserialization: false,
    })
  );
      const nativeError = (method: string) =>
        new KeyValueStore.KeyValueStoreError({
          method,
          message: "Unable to access the persistence store.",
        });
      const scanKeys = Effect.gen(function* scanUpstashKeys() {
        let cursor = "0";
        let keys = HashSet.empty<string>();
        do {
          const page = yield* Effect.tryPromise({
            try: () =>
              client.scan(cursor, {
                match: `${options.keyPrefix}*`,
                count: 100,
              }),
            catch: (cause) => new UpstashPersistenceProviderError({ cause }),
          });
          const [nextCursor, pageKeys] = yield* Schema.decodeUnknownEffect(
            scanPage
          )(page).pipe(
            Effect.mapError(
              () => new UpstashPersistenceProviderError({ cause: undefined })
            )
          );
          cursor = nextCursor;
          keys = HashSet.union(keys, HashSet.fromIterable(pageKeys));
        } while (cursor !== "0");
        return keys;
      });
      const native = KeyValueStore.makeStringOnly({
        get: (logical) =>
          Effect.tryPromise({
            try: () => client.get<string>(key(logical)),
            catch: (cause) => new UpstashPersistenceProviderError({ cause }),
          }).pipe(
            Effect.map((value) => value ?? undefined),
            Effect.mapError(() => nativeError("get"))
          ),
        set: (logical, value) =>
          Effect.tryPromise({
            try: () => client.set(key(logical), value),
            catch: (cause) => new UpstashPersistenceProviderError({ cause }),
          }).pipe(
            Effect.asVoid,
            Effect.mapError(() => nativeError("set"))
          ),
        remove: (logical) =>
          Effect.tryPromise({
            try: () => client.del(key(logical)),
              Effect.map((result) =>
                result === 1 ? ("applied" as const) : ("conflict" as const)
              )
            );
          }).pipe(
            Effect.mapError(
              () =>
                new AtomicKeyValueStoreError({
                  operation: "transact",
                  message: "Unable to apply the atomic key-value transaction.",
                })
            )
          ),
      });
      return Context.empty().pipe(
        Context.add(KeyValueStore.KeyValueStore, native),
        Context.add(AtomicKeyValueStore, atomic)
      );
    })
  );

