import { Context, Effect, Layer } from "effect";
import * as KeyValueStore from "effect/unstable/persistence/KeyValueStore";

import { AtomicKeyValueStore } from "./atomic-key-value-store.service.js";
import { AtomicKeyValueStoreError } from "./errors.js";
import type { UpstashPersistenceClientFactory } from "./upstash-client.internal.js";
import type { UpstashPersistenceOptions } from "./upstash-options.js";

export const makeUpstashPersistenceLayer = (
  options: UpstashPersistenceOptions,
  clientFactory: UpstashPersistenceClientFactory
) => Layer.effectContext(Effect.sync(() => {
  const client = clientFactory();
  const error = (method: string) => new KeyValueStore.KeyValueStoreError({ method, message: "Unable to access the persistence store." });
  const key = (logical: string) => `${options.keyPrefix}${logical}`;
  const native = KeyValueStore.makeStringOnly({
    get: (logical) => Effect.tryPromise({ try: () => client.get(key(logical)), catch: () => error("get") }).pipe(Effect.map((value) => typeof value === "string" ? value : undefined)),
    set: (logical, value) => Effect.tryPromise({ try: () => client.set(key(logical), value), catch: () => error("set") }).pipe(Effect.asVoid),
    remove: (logical) => Effect.tryPromise({ try: () => client.del(key(logical)), catch: () => error("remove") }).pipe(Effect.asVoid),
    clear: Effect.void,
    size: Effect.succeed(0)
  });
  const atomic = AtomicKeyValueStore.of({ transact: () => Effect.fail(new AtomicKeyValueStoreError({ operation: "transact", message: "Unable to apply the atomic key-value transaction." })) });
  return Context.empty().pipe(Context.add(KeyValueStore.KeyValueStore, native), Context.add(AtomicKeyValueStore, atomic));
}));

