import { assert, it } from "@effect/vitest";
import { Duration, Effect, Redacted, Schema } from "effect";

import { AtomicKeyValueStore } from "../src/index.js";
import { makeUpstashPersistenceLayer, serializeUpstashAtomicCommand, upstashAtomicTransactionScript } from "../src/upstash-layer.internal.js";
import type { UpstashPersistenceClient } from "../src/upstash-client.internal.js";

const options = { keyPrefix: "test:persistence:", restToken: Redacted.make("token"), restUrl: Redacted.make("https://example.upstash.io") };

const transaction = {
  conditions: [
    { _tag: "Absent" as const, key: "a" },
    { _tag: "Equals" as const, key: "b", value: "before" },
  ],
  mutations: [
    { _tag: "Set" as const, key: "a", value: "lease", ttl: Duration.millis(25) },
    { _tag: "Remove" as const, key: "b" },
    { _tag: "Set" as const, key: "c", value: "durable" },
  ],
};

it.effect("serializes one physical key per logical transaction key", () =>
  Effect.gen(function* serializationContract() {
    const command = yield* serializeUpstashAtomicCommand(transaction, options.keyPrefix);
    assert.deepStrictEqual(command.keys, ["test:persistence:a", "test:persistence:b", "test:persistence:c"]);
    assert.deepStrictEqual(command.args, ["2", "a", "1", "e", "2", "before", "3", "s", "1", "lease", "25", "r", "2", "s", "3", "durable", ""]);
  })
);

it.effect("evaluates one static atomic command and maps response outcomes", () => {
  const calls: Array<readonly [string, readonly string[], readonly string[]]> = [];
  const client: UpstashPersistenceClient = {
    get: () => Promise.resolve(null), set: () => Promise.resolve(), del: () => Promise.resolve(), scan: () => Promise.resolve(["0", []]),
    eval: (script, keys, args) => { calls.push([script, keys, args]); return Promise.resolve(1); },
  };
  return Effect.gen(function* evalContract() {
    const atomic = yield* AtomicKeyValueStore;
    assert.strictEqual(yield* atomic.transact(transaction), "applied");
    assert.strictEqual(calls.length, 1);
    assert.strictEqual(calls[0]?.[0], upstashAtomicTransactionScript);
    assert.deepStrictEqual(calls[0]?.[1], ["test:persistence:a", "test:persistence:b", "test:persistence:c"]);
  }).pipe(Effect.provide(makeUpstashPersistenceLayer(options, () => client)));
});

it.effect("maps malformed and rejected eval responses to safe atomic errors", () => {
  const marker = "private-eval-marker";
  const malformed: UpstashPersistenceClient = { get: () => Promise.resolve(null), set: () => Promise.resolve(), del: () => Promise.resolve(), scan: () => Promise.resolve(["0", []]), eval: () => Promise.resolve({ marker }) };
  return Effect.gen(function* safeEvalErrorContract() {
    const atomic = yield* AtomicKeyValueStore;
    const error = yield* atomic.transact(transaction).pipe(Effect.flip);
    const rendered = Schema.encodeUnknownSync(Schema.UnknownFromJsonString)(error);
    assert.strictEqual(error.operation, "transact");
    assert.strictEqual(rendered.includes(marker), false);
    assert.strictEqual("cause" in error, false);
  }).pipe(Effect.provide(makeUpstashPersistenceLayer(options, () => malformed)));
});

