+it.effect("matches PersistenceMemory for fenced multi-key atomic transitions", () => {
+  const state = new Map<string, string>();
+  const scripts: string[] = [];
+  const client: UpstashPersistenceClient = {
+    get: (key) => Promise.resolve(state.get(key) ?? null),
+    set: (key, value) => { state.set(key, value); return Promise.resolve(); },
+    del: (...keys) => { keys.forEach((key) => state.delete(key)); return Promise.resolve(); },
+    scan: () => Promise.resolve(["0", []]),
+    eval: (script, keys, args) => {
+      scripts.push(script);
+      let offset = 1;
+      const conditionCount = Number(args[0]);
